// Verify X-Twilio-Signature.
//
// Algorithm (verified against Twilio's published test vector before this was
// written): HMAC-SHA1, base64, keyed with the account auth token, over the
// exact public webhook URL followed by every POST parameter sorted by name,
// name and value concatenated with NO delimiters.
//
// Iterates whatever parameters actually arrived. Never a fixed list: Twilio
// adds webhook parameters without notice, and validating against a hardcoded
// set silently starts rejecting valid requests.
const crypto = require('crypto');

// MUST be the exact public URL Twilio signed against. n8n sits behind Caddy and
// internally sees http://n8n:5678/..., which produces a different signature and
// a 403 on every request. Measured, not guessed. Constructed here rather than
// read from X-Forwarded-* so a forged header cannot influence what we verify.
const PUBLIC_URL = 'https://n8n.ryvodigital.com/webhook/twilio-inbound';

const item = $input.first().json;
const headers = item.headers || {};
const params = item.body || {};
const received = headers['x-twilio-signature'] || '';

const token = $env.TWILIO_AUTH_TOKEN;
const expectedSid = $env.TWILIO_ACCOUNT_SID;

function signatureBase(url, p) {
  const keys = Object.keys(p).sort();
  let s = url;
  for (const k of keys) {
    const v = p[k];
    s += k + (v === undefined || v === null ? '' : String(v));
  }
  return s;
}

let valid = false;
let reason = 'signature_mismatch';

if (!token) {
  reason = 'no_auth_token_in_env';
} else if (!received) {
  reason = 'missing_signature_header';
} else {
  const expected = crypto
    .createHmac('sha1', token)
    .update(Buffer.from(signatureBase(PUBLIC_URL, params), 'utf-8'))
    .digest('base64');
  const a = Buffer.from(expected, 'utf-8');
  const b = Buffer.from(received, 'utf-8');
  // Length check first: timingSafeEqual throws on length mismatch.
  if (a.length === b.length && crypto.timingSafeEqual(a, b)) {
    valid = true;
    reason = 'ok';
  }
}

// A valid signature proves the request came from *a* Twilio account. Confirm it
// is OURS before acting on it.
if (valid && expectedSid && params.AccountSid !== expectedSid) {
  valid = false;
  reason = 'account_sid_mismatch';
}

return [{ json: { headers, body: params, _sig: { valid, reason }, _startedAt: new Date().toISOString() } }];

// Normalise the Twilio payload into the shape the rest of the workflow uses.
// Everything downstream of here is channel-agnostic: swapping back to the Meta
// Cloud API should only require changing this node, the signature check and the
// eventual send node.
const src = $('VerifySignature').first().json;
const b = src.body || {};

// Twilio prefixes WhatsApp addresses: 'whatsapp:+351933048230'.
// leads.phone and clients.whatsapp_number store the bare E.164 number.
const strip = (v) => String(v || '').replace(/^whatsapp:/, '').trim();

const numMedia = parseInt(b.NumMedia || '0', 10) || 0;
const media = [];
for (let i = 0; i < numMedia; i++) {
  media.push({ url: b['MediaUrl' + i] || null, contentType: b['MediaContentType' + i] || null });
}

return [{
  json: {
    // Supabase REST base. Not a secret -- the project URL is public by design;
    // access is gated by the service_role key (an encrypted n8n credential) and
    // by RLS being deny-by-default. Single place to change per environment.
    supabaseUrl: 'https://txxkqskhxhwtrhbmwwig.supabase.co',

    messageSid: b.MessageSid || null,
    accountSid: b.AccountSid || null,
    from: strip(b.From),
    to: strip(b.To),
    waId: b.WaId || null,
    profileName: b.ProfileName || null,
    body: b.Body || '',
    numMedia,
    media,
    // NumMedia > 0 with an empty Body is an image/audio/location-only message.
    // Checkpoint A only has to not crash on it; Checkpoint D handles it properly.
    isNonText: numMedia > 0,
    startedAt: src._startedAt,
  }
}];

// Flatten the client lookup and decide whether we know this recipient.
const res = $input.first().json;
const n = $('Normalise').first().json;
const rows = Array.isArray(res.body) ? res.body : [];
const client = rows[0] || null;
const ca = client && Array.isArray(client.client_automations) ? client.client_automations[0] : null;

// Supabase being unreachable (free-tier auto-pause) surfaces as a non-2xx or a
// transport error, NOT as an empty result. Distinguish the two: an empty list
// means 'we do not serve this number', a bad status means 'the platform DB is
// down'. Conflating them would silently drop real leads during an outage.
const httpOk = res.statusCode >= 200 && res.statusCode < 300;

return [{
  json: {
    ...n,
    httpOk,
    statusCode: res.statusCode,
    found: httpOk && !!client && !!ca,
    errorType: !httpOk ? 'platform_db_unreachable' : (!client || !ca ? 'unknown_client' : null),
    clientId: client ? client.id : null,
    clientName: client ? client.name : null,
    clientAutomationId: ca ? ca.id : null,
    config: ca ? ca.config : null,
  }
}];

// Carry forward whether this was a first contact, plus the lead id.
const up = $input.first().json;
const c = $('FlattenClient').first().json;
const prior = $('FindExistingLead').first().json;

const priorRows = Array.isArray(prior.body) ? prior.body : [];
const isNewLead = priorRows.length === 0;
const rows = Array.isArray(up.body) ? up.body : [];
const lead = rows[0] || null;

return [{
  json: {
    ...c,
    isNewLead,
    leadId: lead ? lead.id : (priorRows[0] ? priorRows[0].id : null),
    upsertStatus: up.statusCode,
  }
}];
